import{_ as e,o as t,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const r="/assets/planning-calendar.e8f4d19a.svg",m=JSON.parse('{"title":"Production Planning","description":"","frontmatter":{},"headers":[],"relativePath":"guide/planning/index.md","filePath":"guide/planning/index.md","lastUpdated":1792160883000}'),n={name:"guide/planning/index.md"},i=o('<h1 id="production-planning" tabindex="-1">Production Planning <a class="header-anchor" href="#production-planning" aria-label="Permalink to &quot;Production Planning&quot;">​</a></h1><p>The Production Planning view lets you schedule constructibles (assemblies and modules) on a calendar, manage production priorities, and visualize workload across your production lines.</p><p>Open it from <strong>Production Schedule</strong> in the left menu. It needs the production management module.</p><nav class="table-of-contents"><ul><li><a href="#calendar-view">Calendar View</a><ul><li><a href="#visual-indicators">Visual Indicators</a></li></ul></li><li><a href="#scheduling-constructibles">Scheduling Constructibles</a><ul><li><a href="#drag-and-drop">Drag and Drop</a></li><li><a href="#closed-days">Closed days</a></li><li><a href="#priority">Priority</a></li><li><a href="#day-menu">Day menu</a></li><li><a href="#multi-select">Multi-Select</a></li></ul></li><li><a href="#filters">Filters</a></li><li><a href="#settings">Settings</a></li><li><a href="#workload">Workload</a></li><li><a href="#saving-changes">Saving Changes</a></li></ul></nav><p><img src="'+r+'" alt="The Production Planning calendar"></p><ol><li>The production line, the projects and the first month shown.</li><li><strong>Reload</strong> and <strong>Save changes</strong>, enabled while there are unsaved changes. The cog opens the settings.</li><li>The constructibles with no date yet. Drag one onto a day.</li><li>The workload of the day. See <a href="#workload">Workload</a>.</li><li>The selected constructible: green.</li><li>A modified constructible, not saved yet: orange.</li><li>A constructible that is past its date and not ready: red.</li></ol><h2 id="calendar-view" tabindex="-1">Calendar View <a class="header-anchor" href="#calendar-view" aria-label="Permalink to &quot;Calendar View&quot;">​</a></h2><p>Pick a <strong>production line</strong> in the toolbar first: the calendar appears once a line is selected. It displays 1 to 4 months at a time, starting from the <strong>Planning Month</strong> chosen in the toolbar, with each day showing the constructibles of that line scheduled for production on that date. Items are ordered by priority within each day. Week numbers are shown next to each week.</p><h3 id="visual-indicators" tabindex="-1">Visual Indicators <a class="header-anchor" href="#visual-indicators" aria-label="Permalink to &quot;Visual Indicators&quot;">​</a></h3><ul><li><strong>Green</strong> — Selected constructible.</li><li><strong>Orange</strong> — Modified (unsaved changes).</li><li><strong>Red</strong> — Overdue (past scheduled date, not yet ready).</li><li><strong>Grey</strong> — Past dates, already ready.</li><li><strong>Blue</strong> — Normal scheduled item.</li></ul><h2 id="scheduling-constructibles" tabindex="-1">Scheduling Constructibles <a class="header-anchor" href="#scheduling-constructibles" aria-label="Permalink to &quot;Scheduling Constructibles&quot;">​</a></h2><h3 id="drag-and-drop" tabindex="-1">Drag and Drop <a class="header-anchor" href="#drag-and-drop" aria-label="Permalink to &quot;Drag and Drop&quot;">​</a></h3><p>Drag a constructible from one date to another to reschedule it. While you drag, the card follows the cursor and the day it would land on is outlined; it moves when you let go. You can also drag items from the <strong>Unscheduled constructibles</strong> panel above the calendar into a date, or drag a scheduled item back onto that panel to remove its date. The panel is shown when <strong>Show Unscheduled</strong> is on in the settings.</p><p>Each week is as tall as its fullest day, with some room under the last card to drop one more.</p><h3 id="closed-days" tabindex="-1">Closed days <a class="header-anchor" href="#closed-days" aria-label="Permalink to &quot;Closed days&quot;">​</a></h3><p>The closed days of the <a href="/guide/management/#work-calendar">work calendar</a> are striped and marked <strong>Closed</strong>. Their capacity is 0, and when something is planned on one, the label and the workload bar turn red. Dragging onto a closed day is allowed, and the card being dragged says <strong>Closed</strong>.</p><h3 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to &quot;Priority&quot;">​</a></h3><p>Within a single day, constructibles are produced in priority order (1 = first). Use the up/down arrows on a card to reorder items within a date.</p><h3 id="day-menu" tabindex="-1">Day menu <a class="header-anchor" href="#day-menu" aria-label="Permalink to &quot;Day menu&quot;">​</a></h3><p>Click a day number to open its menu:</p><ul><li><strong>Shift constructibles</strong> — Move everything on that day to a new date. Two options: also shift the constructibles scheduled after that date by the same number of days, and count only the shown weekdays and skip closed days (so weekends and holidays can be skipped). Shifting to an earlier date counts backwards.</li><li><strong>Day work capacity</strong> — Set the work capacity of that date for the selected production line, in minutes. This is saved on the line and used by the workload bar.</li><li><strong>Constructible sorting</strong> — Reorder the constructibles of that day by dragging them, or sort them by design, by custom column or by project.</li></ul><h3 id="multi-select" tabindex="-1">Multi-Select <a class="header-anchor" href="#multi-select" aria-label="Permalink to &quot;Multi-Select&quot;">​</a></h3><ul><li><strong>Ctrl+Click</strong> — Select multiple individual items.</li><li><strong>Shift+Click</strong> — Select a range of items.</li></ul><p>This allows you to move or modify several constructibles at once.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><ul><li><strong>Production line</strong> — Show only constructibles assigned to a specific line. Required.</li><li><strong>Projects</strong> — Filter by one or more projects.</li><li><strong>Planning Month</strong> — The first month shown.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Click the settings icon to configure the calendar display. The menu groups the calendar, the workload and the card fields:</p><table><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Months to show</strong></td><td>Show 1 to 4 months at a time.</td></tr><tr><td><strong>Show Unscheduled</strong></td><td>Show or hide the <strong>Unscheduled constructibles</strong> panel.</td></tr><tr><td><strong>Show Ready</strong></td><td>Show or hide constructibles that are already ready.</td></tr><tr><td><strong>Show workload</strong></td><td>Show a workload bar on each calendar date.</td></tr><tr><td><strong>Tweak PL work capacity</strong></td><td>Replace the line&#39;s daily capacity (minutes per date) while you plan.</td></tr><tr><td><strong>Shown Weekdays</strong></td><td>Tap the days of the week to display. Until you change them, these are the days with work time in the work calendar; <strong>Use the work calendar days</strong> puts them back.</td></tr><tr><td><strong>Constructible fields</strong></td><td>Select which data to show on each card: design name, client order ID, project, superproject, UUID, status.</td></tr></tbody></table><p>These settings are remembered in your browser, except <strong>Tweak PL work capacity</strong>, which is cleared when you change the production line or reload the page.</p><h2 id="workload" tabindex="-1">Workload <a class="header-anchor" href="#workload" aria-label="Permalink to &quot;Workload&quot;">​</a></h2><p>When <strong>Show workload</strong> is on, each calendar date shows a bar with a percentage: the total expected production time for that day compared to the day&#39;s capacity. Hover the bar to see the expected time of each constructible, the total, the day capacity and where it comes from. An empty day shows an empty bar. When no capacity is known, the bar shows the expected time in minutes.</p><p>The bar is red up to 50 %, orange up to 90 %, green up to 100 % and blue above 100 % (overloaded).</p><p>The workload is calculated from:</p><ul><li>Design area (m²) of each scheduled constructible</li><li><strong>Expected worktime</strong> per m² of each station of the line that works on the design</li><li>The day&#39;s capacity, the first of: <ol><li>the <strong>Day work capacity</strong> set for that date;</li><li>0 on a closed day of the work calendar;</li><li><strong>Tweak PL work capacity</strong>, or the line&#39;s <strong>Worktime Capacity</strong> (minutes per day);</li><li>the hours of the work calendar for that weekday, without the breaks. A Friday that ends at noon has a smaller capacity than a Monday.</li></ol></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use <strong>Tweak PL work capacity</strong> in the settings to try a different daily capacity (for example overtime or reduced shifts) without changing the line. Use <strong>Day work capacity</strong> in the day menu to store a different capacity for one date.</p></div><h2 id="saving-changes" tabindex="-1">Saving Changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to &quot;Saving Changes&quot;">​</a></h2><p>After making scheduling changes, click <strong>Save changes</strong> to persist the updated dates and priorities. Unsaved changes are highlighted in orange. <strong>Reload</strong> discards them and loads the calendar again. Both buttons are active only while there are unsaved changes.</p>',38),s=[i];function l(d,h,c,u,g,p){return t(),a("div",null,s)}const w=e(n,[["render",l]]);export{m as __pageData,w as default};
